 1	method RemoveElement(s: array<int>, k: int) returns (v: array<int>)
 2	    requires 0 <= k < s.Length
 3	    ensures v.Length == s.Length - 1
 4	    ensures forall i :: 0 <= i < k ==> v[i] == s[i]
 5	    ensures forall i :: k <= i < v.Length ==> v[i] == s[i + 1]
 6	{
 7	    v := new int[s.Length - 1];
 8	    var i := 0;
 9	    while i < k
10	        invariant 0 <= i <= k
11	        invariant forall j :: 0 <= j < i ==> v[j] == s[j]
12	    {
13	        v[i] := s[i];
14	        i := i + 1;
15	    }
16	    assert forall i :: 0 <= i < k ==> v[i] == s[i];
17	    while i < v.Length
18	        invariant k <= i <= (v.Length) + 1
19	        invariant forall j :: k <= j < i ==> v[j] == s[j + 1]
20	        invariant forall i :: 0 <= i < k ==> v[i] == s[i]
21	    {
22	        v[i] := s[i + 1];
23	        i := i + 1;
24	    }
25	}

